    def __init__(self, in_features, out_features):
        super().__init__()
        self.linear = nn.Linear(in_features, out_features)
        self._ext = _gelu_softmax_ext

    def forward(self, x):
        x = self.linear(x)
        return self._ext.gelu_softmax_hip(x)


