# FP32 optimized, one block per row.
source = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>

// tanh-based GELU approximation
__device__ __forceinline__ float gelu_fwd(float x) {
    // 0.5*x*(1+tanh(sqrt(2/pi)*(x+0.044715*x^3)))
    const float k0 = 0.7978845608028654f; // sqrt(2/pi)
    const float k1 = 0.044715f;
    float x3 = x * x * x;
    float u = k0 * (x + k1 * x3);
    float t = tanhf(u);
    return 0.5f * x * (1.0f + t);
}

template<int THREADS>
__global__ void gelu_softmax_row_kernel(const float* __restrict__ inp, float* __restrict__ out, int cols) {
    // one block per row
    int row = (int)blockIdx.x;
    int tid = (int)threadIdx.x;

    // Step 1: compute max of GELU(x)
    float local_max = -INFINITY;
    int base = row * cols;
    for (int c = tid; c < cols; c += THREADS) {
        float v = gelu_fwd(inp[base + c]);
        local_max = fmaxf(local_max, v);
    }

    __shared__ float smax[THREADS];
    smax[tid] = local_max;
    __syncthreads();

    // reduce max
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) smax[tid] = fmaxf(smax[tid], smax[tid + offset]);
        __syncthreads();
    }
    float row_max = smax[0];

    // Step 2: compute sum exp(GELU(x)-max)
    float local_sum = 0.0f;
    for (int c = tid; c < cols; c += THREADS) {
        float v = gelu_fwd(inp[base + c]);
        local_sum += __expf(v - row_max);
    }

    __shared__ float ssum[THREADS];
    ssum[tid] = local_sum;
    __syncthreads();

    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) ssum[tid] += ssum[tid + offset];
        __syncthreads();
    }
    float inv_denom = 1.0f / ssum[0];

    // Step 3: write outputs
    for (int c = tid; c < cols; c += THREADS) {
        float v = gelu_fwd(inp[base + c]);
        float e = __expf(v - row_max);
        out[base + c] = e * inv_denom;
    }
}

torch::Tensor gelu_softmax_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");

    auto B = (int)x.size(0);
    auto N = (int)x.size(1);
    auto out = torch::empty_like(x);

    constexpr int THREADS = 256;
    dim3 block(THREADS);
    dim3 grid(B);

